/**
 * Structural guards over the ADMIN / STAFF server actions.
 *
 * `test/customer-actions-guards.test.ts` proves that every export of the
 * CUSTOMER-facing action modules identifies its caller — but its file list stops
 * at the customer surface, so the admin-only modules (refunds, staff roles, node
 * lifecycle, abuse, gift codes, mass mail…) had no equivalent net. Every export
 * of a `"use server"` file is a public network endpoint reachable by curl, so an
 * admin action whose `requireAdmin()`/`requireArea()` was dropped in a refactor
 * would be a privilege hole with nothing to catch it. This is that net.
 *
 * A guard here is not merely "authenticates" — it must be the RIGHT authority.
 * The area/role each module enforces is asserted separately (see EXPECTED below),
 * so a module cannot pass by swapping `requireAdmin` for a bare `requireUser`.
 *
 * Source is comment-stripped first: this repo documents its incidents in the code
 * and a raw grep matches the note, not the call. See test/_source-tools.ts.
 */

const LIB = join(import.meta.dirname, "..", "lib");
const source = (file: string) => stripComments(readFileSync(join(LIB, file), "utf8"));

function exportedActions(src: string): string[] {
  return [...src.matchAll(/export\s+async\s+function\s+([A-Za-z0-9_$]+)\s*\(/g)].map((m) => m[1]);
}

/** Brace-matched body of an exported async function (skips return-type braces). */
function bodyOf(src: string, name: string): string {
